import json,hashlib
D={'pages':[],'units':[],'boundary_notes':[],'review_notes':[],'completed':False};OUT='/workspace/recovery/agent329/replayed-scratch/batch429-438.json'
def save():json.dump(D,open(OUT,'w'),ensure_ascii=False,indent=2)
def p(n,rows):
 pars=[]
 for i,(ar,ru) in enumerate(rows,1):
  id=f'v4-p{n:03}-{i:02}';pars.append(dict(id=id,ar=ar,sha256=hashlib.sha256(ar.encode()).hexdigest(),witness='uploaded_2019_control_pdf',source_complete=True));D['units'].append(dict(id=id+'-ru',source_ids=[id],printed_pages=[n],ar=ar,ru=ru,draft_status='draft',print_collation='control_image_read',independent_human_review=False))
 D['pages'].append(dict(printed_page=n,pdf_leaf=n,witness_status='control_print_visually_read',publisher_footnote_text_imported=False,paragraphs=pars));save()
def merge(a,b):
 x=next(x for x in D['units'] if a in x['source_ids']);y=next(x for x in D['units'] if b in x['source_ids']);x['source_ids']+=y['source_ids'];x['printed_pages']+=y['printed_pages'];x['ar']+=' '+y['ar'];x['ru']+=' '+y['ru'];D['units'].remove(y);save()
p(429,[('فهم أعظم الطوائف تكلفا، وأقلهم تحصيلا للعلم النافع والعمل الصالح.','Они больше всех прочих групп предаются искусственности и меньше всех обретают полезное знание и совершают праведные дела.'),('وكذلك المتكلفون من أصحاب الإرادة والسلوك وأرباب الحال والمقام والوقت والمكان، والبادي والباده والوارد والخاطر والواقع والقادح واللامع، والغيبة والحضور، والمحو والمحق والسحق، والسكر والصحو، واللوائح والطوالع، والعطش والدهش، والتلبيس، والتمكين والتلوين، والاسم والرسم، والجمع وجمع الجمع وجمع الشواهد وجمع الوجود، والأثر والكون والبون، والاتصال والانفصال، والمسامرة والمشاهدة والمعاينة، والتجلي والتحلي والتخلي، وأنا بلا أنا، وأنت بلا أنت، ونحن بلا نحن، وهو بلا هو.','Таковы и предающиеся искусственности среди людей стремления и духовного пути, обладателей состояния и стоянки, времени и места, начального явления (бади), внезапного озарения (бадах), приходящего переживания (варид), помысла (хатыр), западающего в сердце (ваки), вспышки (кадих), проблеска (лами), отсутствия и присутствия, стирания, уничтожения и сокрушения, опьянения и трезвости, мерцаний и восходящих озарений, жажды и изумления, сокрытия, утверждённости и переменчивости, имени и следа, сосредоточения, сосредоточения сосредоточения, сосредоточения свидетельств и сосредоточения существования, следа, бытия и раздельности, соединения и разъединения, ночной беседы, созерцания и непосредственного видения, проявления, облачения в качества и освобождения от них, «я без я», «ты без ты», «мы без мы» и «он без он».'),('وكل ذلك أدنى إشارة إلى تكلف هؤلاء الطوائف وتنطعهم. وكذلك كثير من المنتسبين إلى الفقه، لهم مثل هذا التكلف أو أعظم منه.','Всё это — лишь самое малое указание на искусственность и чрезмерную изощрённость этих групп. Подобная или ещё большая искусственность присуща и многим причисляющим себя к знатокам фикха.'),('فكل هؤلاء محجوبون بما لديهم، موقوفون على ما عندهم. خاضوا بزعمهم بحار العلم، وما ابتلت أقدامهم. وكدوا أفكارهم وأذهانهم وخواطرهم، وما استنارت بالعلم الموروث عن الرسل قلوبهم وأفهامهم! فرحين بما عندهم من العلوم، راضين بما قيدوا به من الرسوم. فهم في واد ورسول الله صلى الله عليه وسلم وأصحابه رضي الله عنهم في واد! والله يعلم أنا لم نتجاوز فيهم','Все они закрыты завесой того, чем располагают, и остановились на том, что имеют. По их мнению, они погрузились в моря знания, хотя не намочили даже ног. Они изнурили свои мысли, умы и помыслы, но их сердца и понимание так и не озарились знанием, унаследованным от посланников! Они радуются своим наукам и довольны схемами, которыми связаны. Они в одной долине, а Посланник Аллаха, да благословит его Аллах и приветствует, и его сподвижники, да будет доволен ими Аллах, — в другой! Аллах знает, что мы не преступили в словах о них')])
p(430,[('القول، بل قصرنا فيما ينبغي لنا أن نقوله، فذكرنا غيضا من فيض، وقليلا من كثير.','меры, а, напротив, сказали меньше, чем следовало: упомянули лишь каплю из потока и малую часть многого.'),('وهؤلاء كلهم داخلون تحت الرأي الذي اتفق السلف على ذمه وذم أهله، فهم أهل الرأي حقا، الذين قال فيهم عمر بن الخطاب رضي الله عنه: إياكم وأصحاب الرأي، فإنهم أعداء السنن. أعيتهم الأحاديث أن يحفظوها، فقالوا بالرأي، فضلوا وأضلوا.','Все они подпадают под то следование личному мнению, которое предшественники единогласно порицали вместе с его приверженцами. Именно они — настоящие приверженцы личного мнения, о которых Умар ибн аль-Хаттаб, да будет доволен им Аллах, сказал: «Остерегайтесь приверженцев личного мнения: они — враги сунн. Они не смогли запомнить хадисы и стали высказываться по личному мнению, заблудились сами и ввели в заблуждение других».'),('وقال أيضا: أصبح أصحاب الرأي أعداء السنن، أعيتهم أن يعوها، وتفلتت أن يرووها، فاشتقوها بالرأي.','Он также сказал: «Приверженцы личного мнения стали врагами сунн. Они не смогли вместить их, а те ускользнули от них, так что они не смогли передавать их; и они стали выводить их из личного мнения».'),('وقال أبو بكر الصديق رضي الله عنه: أي أرض تقلني، وأي سماء تظلني، إن قلت في كتاب الله برأيي أو بما لا أعلم؟','Абу Бакр ас-Сиддик, да будет доволен им Аллах, сказал: «Какая земля понесёт меня и какое небо укроет меня, если я стану говорить о Книге Аллаха по своему мнению или говорить то, чего не знаю?»')])
p(431,[('وقال عمر رضي الله عنه: يا أيها الناس، إن الرأي إنما كان من رسول الله صلى الله عليه وسلم مصيبا لأن الله كان يريه، وإنما هو منا الظن والتكلف.','Умар, да будет доволен им Аллах, сказал: «Люди! Мнение было верным у Посланника Аллаха, да благословит его Аллах и приветствует, потому что Аллах показывал ему истину. У нас же это лишь предположение и искусственность».'),('وقال ابن عباس رضي الله عنهما: من أحدث رأيا ليس في كتاب الله ولم تمض به سنة رسول الله صلى الله عليه وسلم لم يدر على ما هو منه إذا لقي الله عز وجل.','Ибн Аббас, да будет доволен Аллах ими обоими, сказал: «Кто изобретёт мнение, которого нет в Книге Аллаха и которое не утвердила сунна Посланника Аллаха, да благословит его Аллах и приветствует, тот, встретив Аллаха, Велик Он и Могуч, не будет знать, в каком положении из-за этого окажется».'),('وقال عمر رضي الله عنه: يا أيها الناس، اتهموا رأيكم على الدين، فلقد رأيتني وإني لأرد أمر رسول الله صلى الله عليه وسلم برأيي، أجتهد، ووالله ما آلو ذلك يوم أبي جندل، والكاتب يكتب، فقالوا: نكتب: «باسمك اللهم»، فرضي رسول الله صلى الله عليه وسلم وأبيت، فقال: «يا عمر، تراني قد رضيت، وتأبى؟».','Умар, да будет доволен им Аллах, сказал: «Люди! Подвергайте сомнению своё мнение в вопросах религии. Ведь я сам пытался отвергнуть повеление Посланника Аллаха, да благословит его Аллах и приветствует, исходя из собственного мнения, прилагая усилия; клянусь Аллахом, я не жалел их в день Абу Джандаля. Писец записывал, и они сказали: “Напишем: «С именем Твоим, о Аллах»”. Посланник Аллаха, да благословит его Аллах и приветствует, согласился, а я отказался. Он сказал: “Умар! Ты видишь, что я согласился, а сам отказываешься?”»'),('وقال صلى الله عليه وسلم في الحديث الذي رويناه من طريق مسدد، حدثنا يحيى بن سعيد، عن ابن جريج، أخبرني سليمان بن عتيق، عن طلق بن حبيب، عن الأحنف بن قيس، عن عبد الله بن مسعود عن النبي صلى الله عليه وسلم قال: «ألا هلك المتنطعون، ألا هلك المتنطعون، ألا هلك المتنطعون» وإن لم تكن هذه','Он, да благословит его Аллах и приветствует, сказал в хадисе, который мы передали через Мусаддада: нам рассказал Яхья ибн Саид со слов Ибн Джурайджа, которому сообщил Сулейман ибн Атик, передавший от Талька ибн Хабиба, от аль-Ахнафа ибн Кайса, от Абдуллаха ибн Масуда, что Пророк, да благословит его Аллах и приветствует, сказал: «Поистине, погибли чрезмерно изощряющиеся! Поистине, погибли чрезмерно изощряющиеся! Поистине, погибли чрезмерно изощряющиеся!» Если же эти')])
p(432,[('الألفاظ والمعاني التي نجدها في كثير من كلام هؤلاء تنطعا فليس للتنطع حقيقة.','выражения и смыслы, которые мы находим во множестве высказываний этих людей, не являются чрезмерной изощрённостью, тогда у чрезмерной изощрённости вообще нет реального содержания.'),('فصل','Раздел'),('فإن لم يسمح قلبك بكون التوبة غاية مقامات السالكين، ولم تصغ إلى شيء مما ذكرنا، وأبيت إلا أن يكون تلاشي نهاية الاتصال في عين الوجود محقا، وتلاشي علوم الشواهد في العلم اللدني صرفا، وجمع الوجود وجمع العين= هو غاية مقامات السالكين إلى الله، بحيث يدخل في ذلك كل سالك؛ فاعلم أن هذا الجمع المذكور بمجرده لا يعطي عبودية ولا إيمانا، فضلا عن أن يكون غاية كل نبي وولي وعارف؛ فإن هذا الجمع يحصل للصديق والزنديق، ولملاحدة الاتحادية منه حظ كبير، وحوله يدندنون، وهو عندهم نهاية التحقيق! فأين تحقيق العبودية والقيام بأعبائها واحتمال فرائضها وسننها وآدابها، والجهاد لأعداء الله، والدعوة إلى الله، والأمر بالمعروف والنهي عن المنكر، وتحمل الأذى في الله= في هذا الجمع؟ وأين معرفة الأسماء والصفات فيه مفصلا؟ وأين معرفة ما يحبه الرب تعالى ويكرهه فيه مفصلا؟ وأين معرفة خير الخيرين وشر الشرين فيه؟ وأين العلم بمراتب العبودية ومنازلها فيه؟','Если твоё сердце не принимает того, что покаяние — высшая цель стоянок идущих, если ты не внимаешь ничему из сказанного нами и непременно настаиваешь, что полное исчезновение предельного соединения в самой сущности существования, чистое растворение знаний свидетельств в непосредственно дарованном знании, сосредоточение существования и сосредоточение непосредственного видения — это высшая цель стоянок идущих к Аллаху, охватывающая всякого идущего, то знай: само по себе упомянутое сосредоточение не даёт ни рабского служения, ни веры, тем более оно не может быть высшей целью каждого пророка, приближённого и познавшего. Такое сосредоточение бывает и у правдивейшего, и у еретика. У безбожных сторонников единения есть в нём большая доля; вокруг него они и толкуют, считая его вершиной осуществления истины! Но где в этом сосредоточении осуществление рабского служения, исполнение его тягот, несение обязательных и желательных предписаний и правил благонравия, борьба с врагами Аллаха, призыв к Аллаху, побуждение к одобряемому и удержание от порицаемого, терпеливое перенесение обид ради Аллаха? Где в нём подробное познание имён и атрибутов? Где подробное знание того, что Всевышний Господь любит и чего не любит? Где умение различать лучшее из двух благ и худшее из двух зол? Где знание степеней рабского служения и его стоянок?')])
p(433,[('فالحق أن نهاية مقامات السالكين تكميل مرتبة العبودية صرفا، وهذا مما لا سبيل إليه لبني الطبيعة، وإنما خص بذلك الخليلان من بين سائر الخلق. أما إبراهيم الخليل — صلوات الله وسلامه عليه — فإن الله سبحانه شهد له بأنه وفى. وأما سيد ولد آدم — صلوات الله وسلامه عليه — فإنه كمل مرتبة العبودية، فاستحق التقديم على سائر الخلائق، وكان صاحب الوسيلة والشفاعة التي يتأخر عنها جميع الرسل، ويقول هو: «أنا لها». ولهذا ذكره الله سبحانه بالعبودية في أعلى مقاماته وأشرف أحواله، كقوله تعالى: {سُبْحَانَ الَّذِي أَسْرَى بِعَبْدِهِ لَيْلًا} [الإسراء: 1]، وقوله: {وَأَنَّهُ لَمَّا قَامَ عَبْدُ اللَّهِ يَدْعُوهُ} [الجن: 19]، وقوله: {وَإِنْ كُنْتُمْ فِي رَيْبٍ مِمَّا نَزَّلْنَا عَلَى عَبْدِنَا} [البقرة: 23]، وقوله: {تَبَارَكَ الَّذِي نَزَّلَ الْفُرْقَانَ عَلَى عَبْدِهِ} [الفرقان: 1]. ولهذا يقول المسيح حين يرغب إليه في الشفاعة: اذهبوا إلى محمد، عبد غفر الله له ما تقدم من ذنبه وما تأخر. فاستحق تلك الرتبة العليا بتكميل عبوديته لله، وبكمال مغفرة الله له.','Истина в том, что вершина стоянок идущих — полное совершенство степени чистого рабского служения. Это недоступно детям природных склонностей; среди всех творений этим были особо наделены два особых друга Аллаха. Что касается Ибрахима, особого друга Аллаха, да благословит его Аллах и приветствует, то Пречистый Аллах засвидетельствовал, что он исполнил всё сполна. Что же касается господина потомков Адама, да благословит его Аллах и приветствует, то он довёл степень рабского служения до совершенства и заслужил первенство перед всеми творениями. Ему принадлежат «василя» и заступничество, от которого отступят все посланники, тогда как он скажет: «Я возьмусь за это». Именно поэтому Пречистый Аллах упомянул его как раба в высочайших его положениях и благороднейших состояниях. Всевышний сказал: {سُبْحَانَ الَّذِي أَسْرَى بِعَبْدِهِ لَيْلًا} — «Пречист Тот, Кто перенёс ночью Своего раба» [«Аль-Исра», 17:1]; {وَأَنَّهُ لَمَّا قَامَ عَبْدُ اللَّهِ يَدْعُوهُ} — «Когда раб Аллаха встал, взывая к Нему» [«Аль-Джинн», 72:19]; {وَإِنْ كُنْتُمْ فِي رَيْبٍ مِمَّا نَزَّلْنَا عَلَى عَبْدِنَا} — «Если вы сомневаетесь в том, что Мы ниспослали Нашему рабу» [«Аль-Бакара», 2:23]; {تَبَارَكَ الَّذِي نَزَّلَ الْفُرْقَانَ عَلَى عَبْدِهِ} — «Благословен Тот, Кто ниспослал Различение Своему рабу» [«Аль-Фуркан», 25:1]. Поэтому Мессия, когда его попросят о заступничестве, скажет: «Идите к Мухаммаду — рабу, которому Аллах простил прежние и будущие грехи». Эту высочайшую степень он заслужил совершенством своего рабского служения Аллаху и полнотой прощения Аллахом его грехов.'),('فرجع الأمر إلى أن غاية المقامات ونهايتها: هو التوبة والعبودية المحضة، لا جمع العين، ولا جمع الوجود، ولا تلاشي الاتصال.','Итак, всё сводится к тому, что высшая цель и предел стоянок — покаяние и чистое рабское служение, а не сосредоточение непосредственного видения, не сосредоточение существования и не исчезновение соединения.')])
merge('v4-p429-04','v4-p430-01');merge('v4-p431-04','v4-p432-01')
p(434,[('فإن قلت: فهذا الجمع إنما يحصل لمن قام بحقيقة التوبة والعبودية.','Если ты скажешь: «Но это сосредоточение достигается только тем, кто осуществил подлинное покаяние и рабское служение»,'),('قيل: ليس كذلك، بل الجمع الذي يحصل لمن قام بذلك هو جمع الرسل وخلفائهم، وهو جمع الهمة على الله سبحانه محبة وإنابة وتوكلا وخوفا ورجاء ومراقبة، وجمع الهمة على تنفيذ أوامر الله في الخلق دعوة وجهادا. فهما جمعان: جمع للقلب على المعبود وحده، وجمع له على محض عبوديته.','то ответ будет таков: это не так. Сосредоточение, достигаемое тем, кто осуществил это, — сосредоточение посланников и их преемников. Это сосредоточение высшего устремления на Пречистом Аллахе в любви, обращении к Нему, уповании, страхе, надежде и непрестанной внимательности к Нему и сосредоточение высшего устремления на исполнении повелений Аллаха среди творений посредством призыва и борьбы. Это два сосредоточения: сосредоточение сердца на одном лишь Том, Кому поклоняются, и сосредоточение его на чистом рабском служении Ему.'),('فإن قلت: فأين شاهد هذين الجمعين؟','Если ты спросишь: «А где свидетельство этих двух сосредоточений?»'),('قلت: في القرآن كله، فخذه من فاتحة الكتاب في قوله: {إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ} [الفاتحة: 5]. وتأمل ما في قوله: {إِيَّاكَ} من التخصيص لذاته المقدسة بالعبادة والاستعانة، وما في قوله: {نَعْبُدُ} الذي هو للحال والاستقبال وللعبادة الظاهرة والباطنة، من استيفاء أنواع العبادة حالا واستقبالا، قولا وعملا، ظاهرا وباطنا، وما في قوله: {نَسْتَعِينُ} [من] الاستعانة على ذلك به لا بغيره. ولهذا كانت الطريق كلها في هاتين الكلمتين، وهي معنى قولهم: «الطريق في: إياك أريد بما تريد»، فجمع المراد في واحد، والإرادة في مراده الذي يحبه ويرضاه. فإلى هذا دعت الرسل من أولهم إلى آخرهم، وإليه شخص العاملون وتوجه المتوجهون. وكل الأحوال والمقامات — من أولها إلى آخرها — مندرجة في ضمن ذلك، ومن ثمراته وموجباته.','я отвечу: во всём Коране. Возьми его из Открывающей Книгу, из слов: {إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ} — «Тебе одному мы поклоняемся и Тебя одного просим о помощи» [«Аль-Фатиха», 1:5]. Задумайся над тем, как в слове {إِيَّاكَ} — «Тебе одному» — поклонение и обращение за помощью посвящаются исключительно Его святой Сущности. В слове {نَعْبُدُ} — «Мы поклоняемся», которое относится к настоящему и будущему и к внешнему и внутреннему поклонению, охвачены все виды поклонения: в настоящем и будущем, словом и делом, внешне и внутренне. А в слове {نَسْتَعِينُ} — «Просим о помощи» — заключено обращение за помощью в этом к Нему, а не к иному. Поэтому весь путь заключён в этих двух выражениях. В этом и смысл слов: «Путь — в словах: “Тебя я желаю посредством того, чего желаешь Ты”». Искомое сосредоточено в Едином, а стремление — на том, что Он желает, любит и чем доволен. К этому призывали посланники от первого до последнего, к этому устремлялись совершающие дела и обращались обращающиеся. Все состояния и стоянки от начала до конца входят в это и являются его плодами и следствиями.')])
p(435,[('والعبودية تجمع كمال الحب في كمال الذل وكمال الانقياد لمراضي المحبوب وأوامره، فهي الغاية التي ليس فوقها غاية. وإذا لم يكن إلى القيام بحقيقتها كما يجب سبيل، فالتوبة هي المعول والأخية. وقد عرفت بهذا وبغيره أن الحاجة إليها في النهاية أشد من الحاجة إليها في البداية، ولولا تنسم روحها لحال اليأس بين ابن الماء والطين وبين الوصول إلى رب العالمين.','Рабское служение соединяет совершенную любовь с совершенным смирением и совершенным подчинением тому, что угодно Любимому, и Его повелениям. Это высшая цель, над которой нет иной цели. Но поскольку нет пути к осуществлению его подлинной сути так, как должно, покаяние остаётся опорой и надёжной привязью. Из этого и другого ты уже узнал, что нужда в покаянии в конце пути сильнее, чем в начале. Если бы человек не вдыхал его живительного веяния, отчаяние преградило бы потомку воды и глины путь к Господу миров.'),('هذا لو قام بما ينبغي عليه أن يقوم به من حقوق ربه وسيده، فكيف والغفلة والتقصير والتفريط والتهاون وإيثار حظوظه في كثير من الأوقات على حقوق ربه، لا يكاد يتخلص منه، ولا سيما السالك على درب الفناء والجمع؛ فإن ربه يطالبه بالعبودية، ونفسه تطالبه بالجمع والفناء؛ فلو حقق النظر مع نفسه وحاسبها حسابا صحيحا لتبين له أن حظه يريد، ولذته يطلب! نعم، كل أحد يطلب ذلك، لكن الشأن في الفرق بين من صار حظه نفس مرضاة الله ومحابه، أحبت ذلك نفسه أو كرهته، وبين من حظه ما يريده من ربه. فالأول حظه: مراد ربه الديني الشرعي منه، وهذا حظه: مراده من ربه. وبالله التوفيق.','И это было бы так, даже если бы он должным образом исполнял права своего Господа и Владыки. Что же сказать, когда он почти не может избавиться от беспечности, недостатков, упущений, небрежности и частого предпочтения собственной доли правам Господа? Особенно это относится к идущему по тропе фана и сосредоточения: Господь требует от него рабского служения, а душа — сосредоточения и фана. Если бы он внимательно рассмотрел себя и подверг душу правильному отчёту, то увидел бы, что желает собственной доли и ищет собственного наслаждения! Да, этого ищет каждый. Но суть в различии между тем, чья доля — само довольство Аллаха и любимое Им, нравится ли это душе или нет, и тем, чья доля — то, что он сам желает от Господа. Доля первого — то, чего Господь желает от него по религии и Закону; доля второго — то, чего он желает от Господа. Успех дарует Аллах.'),('فإن قيل: هذا الباب مسلم لأهل الذوق، وأنتم تتكلمون بلسان العلم لا بلسان الذوق، والذائق واجد لا يمكنه إنكار موجوده، فلا يرجع إلى صاحب العلم، بل يدعوه إلى ذوق ما ذاقه، ويقول:','Если скажут: «В этом вопросе следует уступить людям вкушения. Вы говорите языком знания, а не языком вкушения. Вкусивший — обретший; он не может отрицать обретённое. Поэтому он не обращается к обладателю знания, а призывает его вкусить то, что вкусил сам, говоря:')])
p(436,[('أقول للائم المهدي ملامته ذق الهوى وإن استطعت الملام لم','Я говорю упрекающему, дарящему мне свой упрёк:\n“Вкуси любовь и, если сможешь упрекать, упрекай”».'),('قيل: لم ينصف من أحال على الذوق، فإنها حوالة على محكوم عليه لا على حاكم، وعلى مشهود عليه لا على شاهد، وعلى موزون لا على ميزان!','то ответим: несправедлив тот, кто отсылает к вкушению, ведь он отсылает к тому, о чём выносят суждение, а не к судье, к тому, о чём свидетельствуют, а не к свидетелю, к взвешиваемому, а не к весам!'),('ويا سبحان الله! هل يدل مجرد ذوق الشيء على حكمه وأنه حق أو باطل؟ وهل جعل الله ورسوله الأذواق والمواجيد حججا وأدلة يميز بها بين ما يحبه ويرضاه، وبين ما يكرهه ويسخطه؟ ولو كان ذلك لاحتج كل مبطل على باطله بالذوق والوجد، كما تجده في كثير من أهل الباطل والإلحاد، فهؤلاء الاتحادية — وهم أكفر الخلق — يحتجون بالذوق والوجد على كفرهم وإلحادهم حتى يقول قائلهم:','Пречист Аллах! Разве само по себе вкушение чего-либо указывает, какое суждение о нём следует вынести и истинно оно или ложно? Разве Аллах и Его Посланник сделали вкушения и сердечные переживания доводами и доказательствами, по которым различают то, что Он любит и чем доволен, и то, чего Он не любит и что вызывает Его гнев? Если бы это было так, всякий приверженец лжи доказывал бы свою ложь вкушением и переживанием, как ты и видишь у многих приверженцев лжи и безбожия. Сторонники единения — самые неверующие из творений — оправдывают своё неверие и безбожие вкушением и переживанием. Один из них даже говорит:'),('يا صاحبي أنت تنهاني وتأمرني والوجد أصدق نهاء وأمار\nفإن أطعك وأعص الوجد رحت عمى عن اليقين إلى أوهام أخبار\nوعين ما أنت تدعوني إليه إذا حققته تره المنهي يا جار','Мой друг! Ты запрещаешь мне и повелеваешь,\nНо переживание правдивее всех запрещающих и повелевающих.\nЕсли послушаюсь тебя и ослушаюсь переживания, уйду слепым\nОт убеждённости к призракам сообщений.\nА само то, к чему ты призываешь меня, если исследуешь его,\nУвидишь тем же запретным, о сосед!'),('ويقول هذا القائل: ثبت عندنا بالكشف والذوق ما يناقض صريح','И этот же человек говорит: «Посредством раскрытия и вкушения для нас установилось то, что противоречит ясному')])
p(437,[('العقل. وكل معتقد لأمر جازم به مستحسن له يذوق طعمه. فالملحد يذوق طعم الإلحاد والانحلال من الدين، والرافضي يذوق طعم الرفض ومعاداة خيار الخلق، والقدري يذوق طعم إنكار القدر ويعجب ممن يثبته، والجبري عكسه. والمشرك يذوق طعم الشرك حتى إنه ليستبشر إذا ذكر إلهه ومعبوده من دون الله، ويشمئز قلبه إذا ذكر الله وحده.','разуму». Всякий, кто твёрдо убеждён в чём-либо и одобряет это, ощущает его вкус. Безбожник вкушает безбожие и освобождение от религии; рафидит вкушает рафидизм и вражду к лучшим из творений; кадарит вкушает отрицание предопределения и удивляется тому, кто его признаёт; у джабрита — наоборот. Многобожник вкушает многобожие: он даже радуется, когда упоминают его божество и то, чему он поклоняется помимо Аллаха, а когда упоминают одного Аллаха, его сердце сжимается от отвращения.'),('وهذا الاحتجاج بالذوق قد سلكه أرباب السماع المحدث الشيطاني الذي هو محض شهوة النفس وهواها، واحتجوا على إباحة هذا السماع بما فيه من الذوق والوجد واللذة. وأنت تجد النصراني له في تثليثه ذوق ووجد وحنين، بحيث لو عرض عليه أشد العذاب لاختاره، دون أن يفارق تثليثه، لما له فيه من الذوق!','К этому доказательству вкушением прибегали и сторонники выдуманного шайтанского слушания, которое представляет собой одну лишь страсть и прихоть души. Они доказывали дозволенность такого слушания тем, что находят в нём вкушение, переживание и наслаждение. Ты обнаружишь, что и христианин испытывает в своей вере в троицу вкушение, переживание и томление, так что, если ему предложат подвергнуться жесточайшей пытке, он предпочтёт её отказу от своей веры в троицу — из-за того вкушения, которое находит в ней!'),('وحينئذ فيقال: هب أن الأمر كما تقول، وأنا المتكلم المنكر لم يتكلم بلسان الذوق، فهل يصح أن يكون ذوق الذائق لذلك حجة صحيحة نافعة له بينه وبين الله؟ وفرضنا أن هذا المنكر قال: نعم، أنا محجوب عن الوصول إلى ما أنكره، غير ذائق له، وأنت ذائق واصل، فما علامة صحة ما ذقته ووصلت إليه؟ وما الدليل عليه؟ وأنا لا أنكر ذوقك له ووجدك به،','Тогда следует сказать: допустим, всё так, как ты говоришь, и я, высказывающий возражение, не говорил языком вкушения. Но может ли вкушение вкусившего быть для него верным, полезным доводом перед Аллахом? Допустим, возражающий сказал: «Да, от меня закрыто достижение того, что я отвергаю, я не вкусил этого, а ты вкусил и достиг. Но каков признак истинности того, что ты вкусил и чего достиг? Каково доказательство этого? Я не отрицаю твоего вкушения и переживания,')])
p(438,[('ولكن الشأن في المذوق لا في الذوق. وإذا ذاق المحب العاشق طعم محبته وعشقه لمحبوبه، ما كان غاية ذلك أن يدل على وجود محبته وعشقه، لا على كون ذلك نافعا له، أو ضارا، أو مرجحا لكماله أو نقصه. وبالله التوفيق.','но дело в том, что вкушают, а не в самом вкушении». Когда любящий, охваченный страстью, вкушает свою любовь и страстную влюблённость в любимого, самое большее, на что это указывает, — существование его любви и страсти. Это не указывает, полезно ли это для него или вредно и способствует ли это его совершенству или недостатку. Успех дарует Аллах.')])
merge('v4-p435-03','v4-p436-01');merge('v4-p436-05','v4-p437-01');merge('v4-p437-03','v4-p438-01')
D['boundary_notes']=[{'printed_page':429,'position':'start','source_id':'v4-p429-01','continuation_of_page':428,'note':'429-01 «فهم أعظم الطوائف...» завершает последний абзац428 «وآخرون أعظم تكلفا...».428 просмотрена для контекста, не импортирована. Необходимо внешнее объединение.'},{'printed_page':438,'position':'end','note':'Конец438 завершает абзац;439 просмотрена для контекста, начинается новый раздел «باب التوحيد», внешнего слияния не нужно.'}];save()
